<?php
namespace Tests\Feature;
use App\Models\{AdPlacement,AdvertisingCampaign,Permission,User}; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Http\UploadedFile; use Illuminate\Support\Facades\Storage; use Tests\TestCase;
class AdvertisingCreativeManagementTest extends TestCase { use RefreshDatabase;
public function test_admin_can_upload_edited_image_creative_and_submit_it():void{Storage::fake('public');$user=User::factory()->create(['email_verified_at'=>now()]);foreach(['view_admin','manage_ad_campaigns'] as $name){$p=Permission::query()->create(['name'=>$name,'label'=>str($name)->replace('_',' ')->title(),'description'=>$name]);$user->permissions()->attach($p);} $campaign=AdvertisingCampaign::factory()->create();$placement=AdPlacement::factory()->create(['width'=>1200,'height'=>300]);$campaign->placements()->attach($placement);$response=$this->actingAs($user)->post('/admin/ad-campaigns/'.$campaign->id.'/creatives',['ad_placement_id'=>$placement->id,'name'=>'Homepage Sponsor','creative_type'=>'image','media_original'=>UploadedFile::fake()->image('source.jpg',1800,900),'media'=>UploadedFile::fake()->image('edited.jpg',1200,300),'media_edit_data'=>json_encode(['preset'=>'ad-'.$placement->id,'outputWidth'=>1200,'outputHeight'=>300]),'width'=>1200,'height'=>300,'headline'=>'Sponsor message','destination_url'=>'https://example.com','alt_text'=>'Sponsor creative']);$response->assertRedirect();$creative=$campaign->creatives()->firstOrFail();$this->assertNotNull($creative->original_media_path);$this->assertNotNull($creative->media_path);$this->assertTrue($creative->is_placement_compatible);$this->actingAs($user)->post('/admin/ad-campaigns/'.$campaign->id.'/creatives/'.$creative->id.'/submit')->assertRedirect();$this->assertSame('submitted',$creative->fresh()->status);}
}
